                  "text": "$ kubectl apply --server-side --field-manager=hire --force-conflicts -f /opt/exam/catalog-hire.yaml\ndeployment.apps/catalog serverside-applied\n\n$ kubectl -n delivery get deploy catalog\nNAME      READY   UP-TO-DATE   AVAILABLE   AGE\ncatalog   3/3     3            3           6d"
